import networkx as nx
import itertools

g = nx.Graph()
g.add_nodes_from(range(12))
g.add_edges_from([(0,10), (0,11), (0,7), (3,10), (2,9), (1,9), (3,6)])

for u in range(12):
    for v in range(u+1, 12):
        if (u, v) not in g.edges and u != v:
            g.add_edge(u, v)

for u in range(12):
    if g.degree(u) < 4:
        for v in range(12):
            if u != v and (u, v) not in g.edges:
                g.add_edge(u, v)
                if g.degree(u) == 4:
                    break

clique_sizes = []
for clique in itertools.chain.from_iterable(itertools.combinations(range(12), r) for r in range(2, 13)):
    if all((u, v) in g.edges or (v, u) in g.edges for u, v in itertools.combinations(clique, 2)):
        clique_sizes.append(len(clique))

if max(clique_sizes) > 4:
    print("UNSATISFIABLE")
else:
    print(g.edges)
